INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES ('129', '20', '6', '6', 'proof', '11', '设 \(A\) 是 \(n\) 阶幂零矩阵，\(A^2=O\)，\(\operatorname{rank}A=r\)，且 \(1\le r<n/2\)。证明存在可逆矩阵 \(P\)，使
\[P^{-1}AP=\begin{pmatrix}O&I_r&O\\O&O&O\\O&O&O\end{pmatrix}.\]', '所给相似标准形存在。', '由 \(A^2=0\) 得 \(\operatorname{Im}A\subset\ker A\)。取像空间的一组基，分别选择原像，再补齐核空间与全空间的基；在此基下，\(A\) 恰具有题示分块形式。', '2019 年第十届全国大学生数学竞赛决赛（非数学专业） 设 (A ) 是 (n ) 阶幂零矩阵， (A 2=O )， ( rank A=r )，且 (1 r<n/2 )。证明存在可逆矩阵 (P )，使 [P -1 AP= pmatrix O&I r&O &O&O &O&O pmatrix . ] 所给相似标准形存在。 由 (A 2=0 ) 得 ( Im A A )。取像空间的一组基，分别选择原像，再补齐核空间与全空间的基；在此基下， (A ) 恰具有题示分块形式。', '2', 'published') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES ('130', '20', '7', '7', 'proof', '11', '设 \(u_n\) 为单调递减的正数列且 \(u_n\to0\)，实数列 \(a_n\) 满足 \(\sum a_nu_n\) 收敛。证明
\[\lim_{n\to\infty}(a_1+a_2+\cdots+a_n)u_n=0.\]', '所给极限为 \(0\)。', '对收敛级数的尾和应用 Abel 变换，并利用 \(1/u_n\) 单调增加，可控制尾部部分和乘以 \(u_n\)；固定的有限首段因 \(u_n\to0\) 也趋于零。', '2019 年第十届全国大学生数学竞赛决赛（非数学专业） 设 (u n ) 为单调递减的正数列且 (u n 0 )，实数列 (a n ) 满足 ( a nu n ) 收敛。证明 [ n (a 1+a 2+ +a n)u n=0. ] 所给极限为 (0 )。 对收敛级数的尾和应用 Abel 变换，并利用 (1/u n ) 单调增加，可控制尾部部分和乘以 (u n )；固定的有限首段因 (u n 0 ) 也趋于零。', '2', 'published') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES ('131', '21', '1', '1', 'calculation', '30', '填空题，共 5 小题，每小题 6 分。

1. 求 \(\displaystyle\lim_{x\to0}\frac{\ln(e^{\sin x}+\sqrt[3]{1-\cos x})-\sin x}{\arctan(4\sqrt[3]{1-\cos x})}\)。
2. 曲线 \(y^2(x-y)=x^2\)，求 \(\displaystyle\int\frac{dx}{y^2}\)。
3. 求 \(\displaystyle\int_0^{\pi/2}\frac{e^x(1+\sin x)}{(1+\cos x)^2}\,dx\)。
4. 求全微分 \(\displaystyle du=\frac{y\,dx-x\,dy}{3x^2-2xy+3y^2}\) 的原函数。
5. 曲面 \(xyz=\mu\) 与椭球 \(x^2/a^2+y^2/b^2+z^2/c^2=1\) 相切，求 \(\mu\)。', '1. \(1/4\)。 2. \(\displaystyle3y/x-2\ln|y/x|+C\)。 3. \(e^{\pi/2}\)。
4. \(\displaystyle u=\frac1{2\sqrt2}\arctan\left[\frac3{2\sqrt2}\left(\frac{x}{y}-\frac13\right)\right]+C\)。
5. \(\displaystyle\mu=\frac{abc}{3\sqrt3}\)。', '1. 展开分子分母的最低阶项。 2. 利用隐式关系令 \(u=y/x\) 化为可积形式。
3. 识别为 \(e^x/(1+\cos x)\) 的导数。 4. 令 \(t=x/y\) 后积分。
5. 用 Lagrange 乘子或 AM-GM 求椭球上 \(xyz\) 的极值。', '2019 年第十一届全国大学生数学竞赛初赛（非数学类） 填空题，共 5 小题，每小题 6 分。 1. 求 ( x 0 (e x + [3] 1- x )- x (4 [3] 1- x ) )。 2. 曲线 (y 2(x-y)=x 2 )，求 ( dx y 2 )。 3. 求 ( 0 /2 e x(1+ x) (1+ x) 2 ,dx )。 4. 求全微分 ( du= y ,dx-x ,dy 3x 2-2xy+3y 2 ) 的原函数。 5. 曲面 (xyz= ) 与椭球 (x 2/a 2+y 2/b 2+z 2/c 2=1 ) 相切，求 ( )。 1. (1/4 )。 2. ( 3y/x-2 |y/x|+C )。 3. (e /2 )。 4. ( u= 1 2 2 [ 3 2 2 ( x y - 13 ) ]+C )。 5. ( = abc 3 3 )。 1. 展开分子分母的最低阶项。 2. 利用隐式关系令 (u=y/x ) 化为可积形式。 3. 识别为 (e x/(1+ x) ) 的导数。 4. 令 (t=x/y ) 后积分。 5. 用 Lagrange 乘子或 AM-GM 求椭球上 (xyz ) 的极值。', '1', 'published') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES ('132', '21', '2', '2', 'calculation', '14', '计算
\[\iiint_\Omega\frac{xyz}{x^2+y^2}\,dx\,dy\,dz,\]
其中 \(\Omega\) 是第一卦限内由 \((x^2+y^2+z^2)^2=2xy\) 围成的区域。', '\(\displaystyle\frac1{72}\)。', '用球坐标 \(x=r\sin\varphi\cos\theta,y=r\sin\varphi\sin\theta,z=r\cos\varphi\)。边界化为 \(r^2=\sin^2\varphi\sin2\theta\)，按第一卦限积分即得 \(1/72\)。', '2019 年第十一届全国大学生数学竞赛初赛（非数学类） 计算 [ xyz x 2+y 2 ,dx ,dy ,dz, ] 其中 ( ) 是第一卦限内由 ((x 2+y 2+z 2) 2=2xy ) 围成的区域。 ( 1 72 )。 用球坐标 (x=r ,y=r ,z=r )。边界化为 (r 2= 2 2 )，按第一卦限积分即得 (1/72 )。', '1', 'published') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES ('133', '21', '3', '3', 'proof', '14', '设 \(f\) 在 \([0,\infty)\) 可导，\(f(0)=0\)，且存在常数 \(A>0\) 使 \(|f''(x)|\le A|f(x)|\)。证明 \(f(x)\equiv0\)。', '\(f\equiv0\)。', '令 \(F(x)=\int_0^x|f(t)|dt\)，则 \(|f(x)|\le A F(x)\)，从而 \(F''(x)\le AF(x)\)、\(F(0)=0\)。乘以 \(e^{-Ax}\) 后得 \(F\equiv0\)。', '2019 年第十一届全国大学生数学竞赛初赛（非数学类） 设 (f ) 在 ([0, ) ) 可导， (f(0)=0 )，且存在常数 (A>0 ) 使 (|f''(x)| A|f(x)| )。证明 (f(x) 0 )。 (f 0 )。 令 (F(x)= 0 x|f(t)|dt )，则 (|f(x)| A F(x) )，从而 (F''(x) AF(x) )、 (F(0)=0 )。乘以 (e -Ax ) 后得 (F 0 )。', '1', 'published') ON CONFLICT (id) DO NOTHING;